import React, { useEffect, useState } from "react";
import axios from "axios";
import { API_URL } from "../config";

function BallotReceiptPage({ auth }) {
  const [votes, setVotes] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetchVotes = async () => {
      try {
        const res = await axios.get(`${API_URL}/api/votes/my`, {
          headers: { Authorization: `Bearer ${auth.token}` },
        });

        setVotes(Array.isArray(res.data) ? res.data : []);
      } catch (err) {
        console.error(err);
      } finally {
        setLoading(false);
      }
    };

    if (auth?.token) fetchVotes();
  }, [auth?.token]);

  const groupedVotes = votes.reduce((acc, vote) => {
    if (!acc[vote.position]) acc[vote.position] = [];
    acc[vote.position].push(vote);
    return acc;
  }, {});

  if (loading) return <p>Loading...</p>;

  return (
    <div style={{ padding: 40 }}>
      <h2>✅ Your Voting Receipt</h2>

      {votes.length === 0 ? (
        <p>No votes found.</p>
      ) : (
        Object.keys(groupedVotes).map((pos) => (
          <div key={pos}>
            <h3>{pos}</h3>

            {groupedVotes[pos].map((v, i) => (
              <div key={i}>
                {v.image && (
                  <img
                    src={`${API_URL}/uploads/${v.image}`}
                    width={50}
                    alt=""
                  />
                )}
                <p>{v.candidateName}</p>
              </div>
            ))}
          </div>
        ))
      )}

      <button onClick={() => window.print()}>
        Print Receipt
      </button>
    </div>
  );
}

export default BallotReceiptPage;
